**Python Error Handling Best Practices**

```python
import logging
from typing import Optional

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Custom exception
class ValidationError(Exception):
    def __init__(self, field: str, message: str):
        self.field = field
        self.message = message
        super().__init__(f"{field}: {message}")

# Specific exception handling
def divide(a: float, b: float) -> float:
    try:
        return a / b
    except ZeroDivisionError:
        logger.error(f"Division by zero: {a}/{b}")
        raise ValueError("Cannot divide by zero")
    except TypeError as e:
        logger.error(f"Type error: {e}")
        raise

# Multiple exception types
def process_data(data: dict) -> str:
    try:
        result = data["key"]["nested"]
        return str(result)
    except KeyError as e:
        raise ValidationError("data", f"Missing key: {e}")
    except (TypeError, AttributeError) as e:
        raise ValidationError("data", f"Invalid structure: {e}")

# Context manager for cleanup
def read_file_safely(path: str) -> Optional[str]:
    try:
        with open(path, 'r') as f:
            return f.read()
    except FileNotFoundError:
        logger.warning(f"File not found: {path}")
        return None
    except PermissionError:
        logger.error(f"Permission denied: {path}")
        raise
    except Exception as e:
        logger.exception(f"Unexpected error reading {path}")
        raise

# Re-raising with context (Python 3.11+)
def fetch_user(user_id: int):
    try:
        # Simulated database call
        raise ConnectionError("Database unreachable")
    except ConnectionError as e:
        raise RuntimeError(f"Failed to fetch user {user_id}") from e

# Finally for cleanup
def process_with_cleanup():
    resource = None
    try:
        resource = acquire_resource()
        return resource.process()
    except Exception:
        logger.exception("Processing failed")
        raise
    finally:
        if resource:
            resource.cleanup()  # Always runs
```

**Key Principles:**
- Catch specific exceptions, not bare `except:`
- Log before re-raising
- Use custom exceptions for domain errors
- Always clean up resources with `finally` or context managers

**JavaScript Async/Await Explained**

**Core Concepts:**

```javascript
// Promise-based (old way)
function fetchUserPromise(id) {
  return fetch(`/api/users/${id}`)
    .then(response => response.json())
    .then(user => {
      console.log(user);
      return user;
    })
    .catch(error => console.error(error));
}

// Async/await (modern way)
async function fetchUser(id) {
  try {
    const response = await fetch(`/api/users/${id}`);
    const user = await response.json();
    console.log(user);
    return user;
  } catch (error) {
    console.error(error);
    throw error;
  }
}
```

**Key Rules:**
```javascript
// 1. async function always returns a Promise
async function getValue() {
  return 42;  // Automatically wrapped in Promise.resolve(42)
}

// 2. await only works inside async functions
async function example() {
  const result = await somePromise();  // ✓ Works
}

function badExample() {
  const result = await somePromise();  // ✗ SyntaxError
}

// 3. Top-level await (ES modules only)
const data = await fetch('/api/data');  // ✓ In .mjs files
```

**Parallel vs Sequential:**
```javascript
// Sequential (slow) - 2 seconds total
async function sequential() {
  const user = await fetchUser();      // 1 sec
  const posts = await fetchPosts();    // 1 sec
  return { user, posts };
}

// Parallel (fast) - 1 second total
async function parallel() {
  const [user, posts] = await Promise.all([
    fetchUser(),      // Both run
    fetchPosts()      // simultaneously
  ]);
  return { user, posts };
}
```

**Error Handling:**
```javascript
// Individual try/catch
async function withErrorHandling() {
  try {
    const data = await riskyOperation();
    return data;
  } catch (error) {
    console.error('Operation failed:', error.message);
    return null;
  }
}

// Promise.allSettled for mixed results
async function fetchAll(urls) {
  const results = await Promise.allSettled(
    urls.map(url => fetch(url))
  );

  results.forEach((result, i) => {
    if (result.status === 'fulfilled') {
      console.log(`${urls[i]}: Success`);
    } else {
      console.log(`${urls[i]}: Failed - ${result.reason}`);
    }
  });
}
```

**Common Patterns:**
```javascript
// Retry with exponential backoff
async function fetchWithRetry(url, maxRetries = 3) {
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fetch(url);
    } catch (error) {
      if (i === maxRetries - 1) throw error;
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
    }
  }
}
```

**Binary Search Implementation**

**Python:**
```python
def binary_search(arr: list[int], target: int) -> int:
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2  # Avoid overflow

        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1  # Not found
```

**JavaScript:**
